#include <bits/stdc++.h>
using namespace std;

vector<int> maxCombinations(int N, int K, vector<int>& A, vector<int>& B) {
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());
    priority_queue<tuple<int, int, int>> pq;  // {sum, aIdx, bIdx}
    for (int i = 0; i < N; ++i) pq.push({A[i] + B[N - 1], i, N - 1});
    vector<int> ans;
    while (!pq.empty() && K-- > 0) {
        auto [sum, x, y] = pq.top(); pq.pop();
        ans.push_back(sum);
        if (y > 0) pq.push({A[x] + B[y - 1], x, y - 1});
    }
    return ans;
}

