import java.util.*;

class Solution {
    public int[] maxCombinations(int[] A, int[] B, int K) {
        Arrays.sort(A); Arrays.sort(B);
        int n = A.length;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);  // {sum, aIdx, bIdx}
        for (int i = 0; i < n; ++i) pq.offer(new int[]{A[i] + B[n - 1], i, n - 1});
        int[] ans = new int[K];
        for (int i = 0; i < K && !pq.isEmpty(); ++i) {
            int[] top = pq.poll();
            ans[i] = top[0];
            if (top[2] > 0) pq.offer(new int[]{A[top[1]] + B[top[2] - 1], top[1], top[2] - 1});
        }
        return ans;
    }
}
